// Real Word files, made with macOS textutil from a one-page resume containing
// a heading, bold and italic text, a bulleted list, a two-row table, non-ASCII
// punctuation (– — ’) and the literal text "<script>alert(1)</script>".
// Used to test the Admin Portal's Word preview (services/wordPreview.ts).

export const RESUME_DOCX_BASE64 =
  '';

export const RESUME_DOC_BASE64 =
  '';

export const fromBase64 = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
